# ============================================================
# Kaggle Codex Studio ONE CELL v21 - restore Codex login refresh flow
# ============================================================
# Túneles permitidos: ngrok, Pinggy, localhost.run. Cero Cloudflare.
# Codex se instala SIEMPRE al arrancar, salvo KAGGLE_CODEX_MOCK=1.
# v21 mantiene v20 y restaura el flujo de login/refresco de Codex en Settings,
# descargas de respuestas/artefactos, backups/restauración VPS configurables,
# skin visual CodexWeb, menú inferior y terminal como pestaña. Sin NPM. Porque compilar Vite en Kaggle
# para un chat sería otra ceremonia absurda.
# ============================================================

import os, sys, subprocess, pathlib, time, re, socket, signal, shutil, urllib.request, threading

os.environ["KAGGLE_TUNNEL_PROVIDER"] = os.environ.get("KAGGLE_TUNNEL_PROVIDER_FORCE", os.environ.get("KAGGLE_TUNNEL_PROVIDER", "auto"))
os.environ.setdefault("KAGGLE_CODEX_MOCK", "0")
os.environ.setdefault("KAGGLE_CODEX_ALWAYS_INSTALL", "1")
os.environ.setdefault("KAGGLE_CODEX_YOLO", "1")
os.environ.setdefault("KAGGLE_CODEX_MAX_PARALLEL", "1")

BASE = pathlib.Path("/kaggle/working/kaggle_codex_studio")
WORKSPACE = pathlib.Path("/kaggle/working/workspace")
RUNTIME = BASE / "runtime"
LOGS = RUNTIME / "logs"
BIN = pathlib.Path("/tmp/kaggle_codex_studio_bin")
CODEX_HOME = RUNTIME / "codex-home"
for p in (BASE, WORKSPACE, RUNTIME, LOGS, BIN, CODEX_HOME):
    p.mkdir(parents=True, exist_ok=True)

BOOTSTRAP_LOG = LOGS / "bootstrap.log"
SERVER_LOG = LOGS / "server.log"

def log(msg=""):
    text = str(msg)
    print(text, flush=True)
    with open(BOOTSTRAP_LOG, "a", encoding="utf-8") as f:
        f.write(text + "\n")

def run(cmd, timeout=300, check=False, env=None):
    log("$ " + " ".join(map(str, cmd)))
    p = subprocess.run(list(map(str, cmd)), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=timeout, env=env)
    if p.stdout:
        log(p.stdout[-8000:])
    if check and p.returncode != 0:
        raise RuntimeError("Comando falló: " + " ".join(map(str, cmd)))
    return p

def have(cmd): return shutil.which(cmd) is not None

def free_port():
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0)); return s.getsockname()[1]

def kill_old():
    try: out = subprocess.check_output(["ps", "-eo", "pid,args"], text=True)
    except Exception: return
    me = os.getpid(); patterns = ["uvicorn app:app", "a.pinggy.io", "localhost.run", "ngrok http"]
    for line in out.splitlines()[1:]:
        try:
            pid_s, args = line.strip().split(None, 1); pid = int(pid_s)
        except Exception: continue
        if pid == me: continue
        if any(x in args for x in patterns):
            try: os.kill(pid, signal.SIGTERM); log(f"Matado proceso viejo pid={pid} args={args[:140]}")
            except Exception: pass

def install_python_deps():
    import importlib.util
    need=[]
    for mod,pkg in [("fastapi","fastapi"),("uvicorn","uvicorn[standard]"),("multipart","python-multipart"),("pydantic","pydantic")]:
        if importlib.util.find_spec(mod) is None: need.append(pkg)
    if need: run([sys.executable,"-m","pip","install","-q",*need], timeout=600, check=True)

def codex_env():
    env=os.environ.copy(); env["CODEX_HOME"]=str(CODEX_HOME); env["CODEX_NON_INTERACTIVE"]="1"; env["NO_COLOR"]="1"; env["TERM"]="dumb"
    env["PATH"]=env.get("PATH","")+os.pathsep+str(pathlib.Path.home()/".local/bin")+os.pathsep+"/root/.local/bin"+os.pathsep+"/usr/local/bin"
    return env

def ensure_codex_installed():
    os.environ["PATH"] = os.environ.get("PATH", "") + os.pathsep + str(pathlib.Path.home()/".local/bin") + os.pathsep + "/root/.local/bin" + os.pathsep + "/usr/local/bin"
    os.environ["CODEX_HOME"] = str(CODEX_HOME)
    if os.environ.get("KAGGLE_CODEX_MOCK", "0") == "1":
        log("🧪 KAGGLE_CODEX_MOCK=1: salto instalación real de Codex."); return
    if os.environ.get("KAGGLE_CODEX_ALWAYS_INSTALL", "1") == "1": log("📦 Instalando/actualizando Codex CLI al arranque.")
    elif have("codex"):
        log("✅ Codex ya está instalado y KAGGLE_CODEX_ALWAYS_INSTALL=0."); run(["codex","--version"], timeout=20, env=codex_env()); return
    installer=BIN/"install_codex.sh"
    try:
        urllib.request.urlretrieve("https://chatgpt.com/codex/install.sh", installer); installer.chmod(0o755); run(["bash", str(installer)], timeout=900, env=codex_env())
    except Exception as e: log(f"⚠️ Instalador standalone falló: {e}")
    if not have("codex") and have("npm"):
        try: log("📦 Fallback npm: npm install -g @openai/codex"); run(["npm","install","-g","@openai/codex"], timeout=900, env=codex_env())
        except Exception as e: log(f"⚠️ Fallback npm falló: {e}")
    if have("codex"):
        log("✅ Codex disponible en PATH."); run(["codex","--version"], timeout=20, env=codex_env())
    else: log("⚠️ Codex no aparece en PATH. La UI queda para diagnóstico.")

def wait_frontend(port):
    import urllib.request
    url=f"http://127.0.0.1:{port}/"; last=""
    for _ in range(60):
        try:
            with urllib.request.urlopen(url, timeout=2) as r:
                if r.status == 200: return True
        except Exception as e: last=repr(e); time.sleep(.25)
    raise RuntimeError("Frontend local no responde: "+last)

def start_ngrok(port):
    token=os.environ.get("KAGGLE_NGROK_AUTHTOKEN","").strip()
    if not token: return None
    run([sys.executable,"-m","pip","install","-q","pyngrok"], timeout=300, check=True)
    from pyngrok import ngrok
    ngrok.set_auth_token(token); return str(ngrok.connect(port,"http").public_url)

def start_pinggy(port):
    if not have("ssh"): return None
    cmd=["ssh","-o","StrictHostKeyChecking=no","-o","ServerAliveInterval=30","-o","ExitOnForwardFailure=yes","-p","443",f"-R0:localhost:{port}","a.pinggy.io"]
    p=subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
    (RUNTIME/"pinggy.pid").write_text(str(p.pid)); deadline=time.time()+60
    while time.time()<deadline:
        line=p.stdout.readline() if p.stdout else ""
        if line:
            log("[pinggy] "+line.rstrip())
            for u in re.findall(r"https://[-a-zA-Z0-9.]+", line):
                host=u.split("://",1)[-1].split("/",1)[0].lower()
                if host in {"dashboard.pinggy.io","pinggy.io","www.pinggy.io"}: continue
                if "pinggy" in host and (host.endswith(".link") or host.endswith(".life") or host.endswith(".site") or host.endswith(".net")): return u.rstrip(".")
        elif p.poll() is not None: return None
        else: time.sleep(.25)
    return None

def start_localhostrun(port):
    if not have("ssh"): return None
    cmd=["ssh","-o","StrictHostKeyChecking=no","-o","ServerAliveInterval=30","-o","ExitOnForwardFailure=yes","-R",f"80:localhost:{port}","localhost.run"]
    p=subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
    (RUNTIME/"localhostrun.pid").write_text(str(p.pid)); deadline=time.time()+60
    while time.time()<deadline:
        line=p.stdout.readline() if p.stdout else ""
        if line:
            log("[localhost.run] "+line.rstrip())
            for u in re.findall(r"https://[-a-zA-Z0-9.]+", line):
                host=u.split("://",1)[-1].split("/",1)[0].lower()
                if host.endswith(".lhr.life") or host.endswith(".localhost.run"): return u.rstrip(".")
        elif p.poll() is not None: return None
        else: time.sleep(.25)
    return None

def create_tunnel(port):
    provider=os.environ.get("KAGGLE_TUNNEL_PROVIDER","auto").strip().lower()
    if provider=="none": return None,"none"
    order=[]
    if provider=="auto":
        if os.environ.get("KAGGLE_NGROK_AUTHTOKEN","").strip(): order.append("ngrok")
        order += ["pinggy","localhostrun"]
    else: order=[provider]
    for item in order:
        try:
            log(f"🌍 Probando túnel {item}...")
            url = start_ngrok(port) if item=="ngrok" else start_pinggy(port) if item=="pinggy" else start_localhostrun(port) if item in ("localhostrun","localhost.run") else None
            if url: return url,item
        except Exception as e: log(f"⚠️ {item} falló: {e}")
    return None,"none"

started=time.time(); log("="*72); log("🚀 Kaggle Codex Studio v21"); log("="*72)
kill_old(); install_python_deps(); ensure_codex_installed()
